<template><article class="product-card"><img :src="image" :alt="product.name"/><div class="product-info"><div><h3>{{product.name}}</h3><p>{{product.description}}</p><strong>¥{{product.price.toLocaleString()}}</strong></div><div class="stepper"><button :disabled="disabled" @click="setQty(product,qty-1)">－</button><span>{{qty}}</span><button :disabled="disabled" @click="setQty(product,qty+1)">＋</button></div></div></article></template><script setup lang="ts">import {computed} from 'vue';import {resolveImageUrl,type Product} from '../api';import {cart,setQty} from '../cart';const props=withDefaults(defineProps<{product:Product;disabled?:boolean}>(),{disabled:false});const qty=computed(()=>cart[props.product.id]||0);const fallback='https://placehold.co/800x520/f3eee4/53645a?text=Toshio+Restaurant';const image=computed(()=>props.product.image.startsWith('/uploads')?`${new URL(import.meta.env.VITE_API_BASE_URL||'http://localhost:3000/api').origin}${props.product.image}`:props.product.image||fallback);</script>

